        Calc sub = (x, y) -> x - y;
        Calc mul = (x, y) -> x * y;
        Calc div = (x, y) -> x / y;
        int result;
        if (op.equals("+")) {
            result = add.apply(a, b);
        } else if (op.equals("-")) {
            result = sub.apply(a, b);
        } else if (op.equals("*")) {
            result = mul.apply(a, b);
        } else {
            result = div.apply(a, b);
        }
        System.out.println(result);
    }
}

